package com.wren.shiftdropblock;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("shiftdropblock")
public interface ShiftDropBlockConfig extends Config
{
    @ConfigItem(
            keyName = "protectedSlots",
            name = "Protected slots",
            description = "Comma-separated inventory slot indices (0-27) to block from being dropped"
    )
    default String protectedSlots()
    {
        return "0";
    }

    @ConfigItem(
            keyName = "protectedItemIds",
            name = "Protected item IDs",
            description = "Comma-separated item IDs to block from being dropped (used when 'Protect by item ID' is on)"
    )
    default String protectedItemIds()
    {
        return "";
    }

    @ConfigItem(
            keyName = "useItemIds",
            name = "Protect by item ID",
            description = "If on, uses item IDs instead of slot indices. Survives inventory rearranging."
    )
    default boolean useItemIds()
    {
        return false;
    }
}

package com.wren.shiftdropblock;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
        name = "Shift Drop Block",
        description = "Prevents shift-click dropping items in protected inventory slots",
        tags = {"inventory", "drop", "protect", "salvage"}
)
public class ShiftDropBlockPlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(ShiftDropBlockPlugin.class);

    @Inject
    private Client client;

    @Inject
    private ShiftDropBlockConfig config;

    private final Set<Integer> protectedSlots = new HashSet<>();
    private final Set<Integer> protectedItemIds = new HashSet<>();

    @Provides
    ShiftDropBlockConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ShiftDropBlockConfig.class);
    }

    @Override
    protected void startUp()
    {
        rebuildSets();
        log.debug("ShiftDropBlock started");
    }

    @Override
    protected void shutDown()
    {
        protectedSlots.clear();
        protectedItemIds.clear();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"shiftdropblock".equals(event.getGroup())) return;
        rebuildSets();
    }

    private void rebuildSets()
    {
        protectedSlots.clear();
        protectedItemIds.clear();
        parseInts(config.protectedSlots(), protectedSlots);
        parseInts(config.protectedItemIds(), protectedItemIds);
    }

    private void parseInts(String csv, Set<Integer> target)
    {
        if (csv == null || csv.isBlank()) return;
        for (String part : csv.split(","))
        {
            String trimmed = part.trim();
            if (trimmed.isEmpty()) continue;
            try
            {
                target.add(Integer.parseInt(trimmed));
            }
            catch (NumberFormatException e)
            {
                log.warn("Could not parse '{}' as int", trimmed);
            }
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (event.getMenuAction() != MenuAction.CC_OP) return;
        if (WidgetUtil.componentToInterface(event.getParam1()) != InterfaceID.INVENTORY) return;
        if (!"Drop".equals(event.getMenuOption())) return;

        int slot = event.getParam0();

        if (config.useItemIds())
        {
            ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
            if (inv == null) return;
            Item item = inv.getItem(slot);
            if (item != null && protectedItemIds.contains(item.getId()))
            {
                event.consume();
                log.debug("Blocked drop of item {} in slot {}", item.getId(), slot);
            }
        }
        else
        {
            if (protectedSlots.contains(slot))
            {
                event.consume();
                log.debug("Blocked drop of slot {}", slot);
            }
        }
    }
}
